#define MAX_N 500
#define MAX_M 5000
#define INF 1000000000

typedef struct {
    int to, next;
    int score;
} Edge;

Edge edges[MAX_M];
int head[MAX_N], edge_cnt;
int dist[MAX_N], prev_node[MAX_N], prev_edge[MAX_N];
int queue[MAX_N * MAX_N], qh, qt;
int in_queue[MAX_N];
int n, m, k;

void add_edge(int u, int v, int s) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].score = s;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int main() {
    scanf("%d %d %d", &n, &m, &k);
    memset(head, -1, sizeof(head));
    edge_cnt = 0;
    for (int i = 0; i < m; i++) {
        int u, v, s;
        scanf("%d %d %d", &u, &v, &s);
        add_edge(u, v, s);
    }

    int best_len = INF;
    int best_start = -1;
    int best_path[MAX_N];
    int best_path_len = 0;

    // Try each possible start node
    for (int start = 0; start < n; start++) {
        // Initialize distances with negative infinity
        for (int i = 0; i < n; i++) {
            dist[i] = -INF;
            prev_node[i] = -1;
            prev_edge[i] = -1;
            in_queue[i] = 0;
        }
        dist[start] = 0;
        qh = qt = 0;
        queue[qt++] = start;
        in_queue[start] = 1;

        // SPFA (Bellman-Ford variant) to find longest path (since scores are integer, we can use this)
        while (qh < qt) {
            int u = queue[qh++];
            in_queue[u] = 0;
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                int w = edges[e].score;
                if (dist[u] + w > dist[v]) {
                    dist[v] = dist[u] + w;
                    prev_node[v] = u;
                    prev_edge[v] = e;
                    if (!in_queue[v]) {
                        queue[qt++] = v;
                        in_queue[v] = 1;
                    }
                }
            }
        }

        // Check if any node reaches score >= k
        for (int end = 0; end < n; end++) {
            if (dist[end] >= k) {
                // Reconstruct path
                int path[MAX_N];
                int len = 0;
                int cur = end;
                while (cur != start) {
                    path[len++] = cur;
                    cur = prev_node[cur];
                }
                path[len++] = start;
                // Reverse to get start->end order
                for (int i = 0; i < len/2; i++) {
                    int tmp = path[i];
                    path[i] = path[len-1-i];
                    path[len-1-i] = tmp;
                }
                if (len < best_len) {
                    best_len = len;
                    best_start = start;
                    best_path_len = len;
                    for (int i = 0; i < len; i++) best_path[i] = path[i];
                }
            }
        }
    }

    if (best_len == INF) {
        printf("-1\n");
        return 0;
    }

    // The number of arrows is best_path_len - 1
    int arrows = best_path_len - 1;
    if (arrows > 100) {
        printf("%d\n", arrows);
    } else {
        printf("%d\n", arrows);
        for (int i = 0; i < best_path_len; i++) {
            if (i > 0) printf(" ");
            printf("%d", best_path[i]);
        }
        printf("\n");
    }

    return 0;
}

