using ll = long long;
const ll INF = (1LL << 60);

struct Edge {
    int to;
    ll w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    ll K;
    cin >> N >> M >> K;

    vector<vector<Edge>> g(N + 1);
    for (int i = 0; i < M; ++i) {
        int u, v;
        ll c;
        cin >> u >> v >> c;
        g[u].push_back({v, c});
    }

    // dp[steps][v] = maximum score achievable ending at v using exactly `steps` edges
    // from any starting vertex.
    // parent[steps][v] = previous vertex used to reach this state.
    vector<ll> prev(N + 1, 0), cur(N + 1, -INF);
    vector<vector<int>> parent; // only needed up to 100 steps for reconstruction
    parent.push_back(vector<int>(N + 1, -1)); // step 0

    // If K <= 0, zero edges suffice; choose any vertex, say 1.
    if (K <= 0) {
        cout << 0 << "\n1\n";
        return 0;
    }

    for (int step = 1; step <= 100; ++step) {
        fill(cur.begin(), cur.end(), -INF);
        vector<int> par(N + 1, -1);

        for (int u = 1; u <= N; ++u) {
            if (prev[u] <= -INF / 2) continue;
            for (auto &e : g[u]) {
                ll cand = prev[u] + e.w;
                if (cand > cur[e.to]) {
                    cur[e.to] = cand;
                    par[e.to] = u;
                }
            }
        }

        // Also allow starting directly and taking one edge at this step sequence:
        // already covered because prev[u]=0 for all u at step 0.

        parent.push_back(par);

        int bestV = -1;
        for (int v = 1; v <= N; ++v) {
            if (cur[v] >= K) {
                bestV = v;
                break;
            }
        }

        if (bestV != -1) {
            // reconstruct any valid path with exactly `step` edges ending at bestV
            vector<int> path;
            int v = bestV;
            path.push_back(v);
            for (int s = step; s >= 1; --s) {
                v = parent[s][v];
                path.push_back(v);
            }
            reverse(path.begin(), path.end());

            cout << step << "\n";
            for (int i = 0; i < (int)path.size(); ++i) {
                if (i) cout << ' ';
                cout << path[i];
            }
            cout << "\n";
            return 0;
        }

        prev.swap(cur);
    }

    // Max-plus matrix multiplication / exponentiation for steps > 100
    // Transition matrix A where A[u][v] = max weight from u to v in one step.
    vector<vector<ll>> A(N, vector<ll>(N, -INF));
    for (int u = 1; u <= N; ++u) {
        for (auto &e : g[u]) {
            A[u - 1][e.to - 1] = max(A[u - 1][e.to - 1], e.w);
        }
    }

    auto mult = [&](const vector<vector<ll>> &X, const vector<vector<ll>> &Y) {
        vector<vector<ll>> Z(N, vector<ll>(N, -INF));
        for (int i = 0; i < N; ++i) {
            for (int k = 0; k < N; ++k) {
                if (X[i][k] <= -INF / 2) continue;
                for (int j = 0; j < N; ++j) {
                    if (Y[k][j] <= -INF / 2) continue;
                    Z[i][j] = max(Z[i][j], X[i][k] + Y[k][j]);
                }
            }
        }
        return Z;
    };

    auto vec_mult = [&](const vector<ll> &vec, const vector<vector<ll>> &Mat) {
        vector<ll> res(N, -INF);
        for (int i = 0; i < N; ++i) {
            if (vec[i] <= -INF / 2) continue;
            for (int j = 0; j < N; ++j) {
                if (Mat[i][j] <= -INF / 2) continue;
                res[j] = max(res[j], vec[i] + Mat[i][j]);
            }
        }
        return res;
    };

    // Initial vector after 0 steps: can start at any vertex with score 0.
    vector<ll> init(N, 0);

    // Precompute powers A^(2^b)
    const int LOG = 62;
    vector<vector<vector<ll>>> pw(LOG);
    pw[0] = A;
    for (int b = 1; b < LOG; ++b) pw[b] = mult(pw[b - 1], pw[b - 1]);

    // Greedily find maximum steps with score < K, then answer is +1 if reachable.
    ll steps = 0;
    vector<ll> curVec = init;

    auto max_entry = [&](const vector<ll> &v) {
        ll mx = -INF;
        for (ll x : v) mx = max(mx, x);
        return mx;
    };

    for (int b = LOG - 1; b >= 0; --b) {
        vector<ll> nxt = vec_mult(curVec, pw[b]);
        if (max_entry(nxt) < K) {
            curVec = move(nxt);
            steps += (1LL << b);
        }
    }

    // Need one more step
    vector<ll> finalVec = vec_mult(curVec, A);
    if (max_entry(finalVec) < K) {
        cout << -1 << "\n";
        return 0;
    }

    cout << (steps + 1) << "\n";
    return 0;
}

import java.util.*;

public class Solution {
    static class State {
        int cone;
        long score;
        int arrows;
        List<Integer> path;

        State(int cone, long score, int arrows, List<Integer> path) {
            this.cone = cone;
            this.score = score;
            this.arrows = arrows;
            this.path = new ArrayList<>(path);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt(); // number of cones
        int M = sc.nextInt(); // number of arrows
        long K = sc.nextLong(); // target score

        // Build adjacency list: for each cone, list of (to, score)
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < M; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int s = sc.nextInt();
            graph.get(u).add(new int[]{v, s});
        }

        // For each starting cone, find minimum arrows to reach score >= K
        int minArrows = Integer.MAX_VALUE;
        List<Integer> bestPath = null;

        for (int start = 0; start < N; start++) {
            // dp[cone][arrows] = max score achievable
            // Since arrows might be large, we use a different approach
            // Use BFS with priority queue on number of arrows

            // Map from cone to best score for given arrows
            // Actually, let's use Dijkstra where cost is arrows and we maximize score

            // Priority queue ordered by arrows (minimum first)
            PriorityQueue<State> pq = new PriorityQueue<>((a, b) -> a.arrows - b.arrows);
            Map<Integer, Long> bestScore = new HashMap<>(); // cone -> best score achieved

            List<Integer> initialPath = new ArrayList<>();
            initialPath.add(start);
            pq.offer(new State(start, 0, 0, initialPath));
            bestScore.put(start, 0L);

            while (!pq.isEmpty()) {
                State curr = pq.poll();

                // If we already found a better path to this cone with same or fewer arrows, skip
                if (bestScore.containsKey(curr.cone) && bestScore.get(curr.cone) > curr.score) {
                    continue;
                }

                // Check if we reached target
                if (curr.score >= K) {
                    if (curr.arrows < minArrows) {
                        minArrows = curr.arrows;
                        bestPath = curr.path;
                    }
                    break; // Since PQ is ordered by arrows, first found is optimal for this start
                }

                // Explore neighbors
                for (int[] edge : graph.get(curr.cone)) {
                    int nextCone = edge[0];
                    int score = edge[1];

                    long newScore = curr.score + score;
                    int newArrows = curr.arrows + 1;

                    // Prune: if we already have a better score with same or fewer arrows, skip
                    if (bestScore.containsKey(nextCone) && bestScore.get(nextCone) >= newScore) {
                        continue;
                    }

                    // Also prune if arrows exceed current best
                    if (newArrows >= minArrows) {
                        continue;
                    }

                    List<Integer> newPath = new ArrayList<>(curr.path);
                    newPath.add(nextCone);

                    pq.offer(new State(nextCone, newScore, newArrows, newPath));
                    bestScore.put(nextCone, newScore);
                }
            }
        }

        if (minArrows == Integer.MAX_VALUE) {
            System.out.println(-1);
        } else if (minArrows > 100) {
            System.out.println(minArrows);
        } else {
            System.out.println(minArrows);
            for (int i = 0; i < bestPath.size(); i++) {
                if (i > 0) System.out.print(" ");
                System.out.print(bestPath.get(i));
            }
            System.out.println();
        }
    }
}

