            int node = (int) cur[0]; long score = cur[1];
            int steps = visited.get(encode(node, score, K))[0];
            for (int[] e : adj[node]) {
                long ns = Math.min(score + e[1], K + 1);
                if (ns >= K) { found = new long[]{node, score, e[0], ns, steps + 1}; queue.clear(); break; }
                long nkey = encode(e[0], ns, K);
                if (!visited.containsKey(nkey)) {
                    visited.put(nkey, new int[]{steps + 1, node, (int) score});
                    queue.add(new long[]{e[0], ns});
                }
            }
            if (found != null) break;
        }
        if (found == null) { System.out.println(-1); return; }
        int arrows = (int) found[4];
        System.out.println(arrows);
        if (arrows <= 100) {
            // reconstruct path
            List<Integer> path = new ArrayList<>();
            path.add((int) found[2]);
            int cn = (int) found[0]; long cs = found[1];
            while (cn != -1) {
                path.add(cn);
                int[] info = visited.get(encode(cn, cs, K));
                int pn = info[1]; long ps = info[2];
                cn = pn; cs = ps;
            }
            Collections.reverse(path);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < path.size(); i++) { if (i > 0) sb.append(' '); sb.append(path.get(i)); }
            System.out.println(sb);
        }
    }
    static long encode(long node, long score, int K) { return node * 200001L + score + 100000; }
}

import java.io.*;
import java.util.*;

/*
Assumptions inferred from the statement:
- Directed graph of cones.
- Each arrow has an integer score.
- We may choose any starting cone.
- Need a walk whose total score is at least K, minimizing number of arrows.
- Output:
  * -1 if impossible
  * otherwise:
      - if answer length <= 100: print length and the sequence of visited cones
      - if answer length > 100: print only the length
- Any optimal path is acceptable.

Input format assumed:
N M K
u1 v1 w1
...
uM vM wM

Vertices are numbered 1..N.

Method:
- Since start is arbitrary, initialize all vertices with distance 0 at step 0.
- DP by exact number of edges:
    dp[t][v] = maximum score achievable ending at v using exactly t edges.
- Transition over all edges.
- The first t such that some dp[t][v] >= K is optimal.
- To reconstruct path for t <= 100, store predecessor vertex for each state.

How far to iterate?
- If there exists a cycle with positive total gain reachable from some start (which is always true if the cycle exists, since any start is allowed),
  then a solution exists for sufficiently large K.
- If no positive cycle exists, best score for any walk is achieved by a simple path, so at most N-1 edges are needed.
- Therefore:
  * Compute SCCs and detect whether any SCC contains a positive cycle.
    Since weights are on edges and SCC is strongly connected, a positive cycle exists in an SCC iff the maximum cycle mean > 0.
    Equivalent practical test: inside each SCC, if after |S| relaxations of "longest path" an improvement still occurs, there is a positive cycle.
  * Let POSITIVE_CYCLE_EXIST be true if any SCC has a positive cycle.
  * If false, only need DP up to N-1.
  * If true, answer exists iff there is at least one edge/path with eventual positive growth; since any SCC with positive cycle can be started from directly, for any finite K there is always a solution eventually.
    Still need minimal number of edges. We can DP until answer found. To avoid huge memory, keep only current/next layers; store parents only up to 100.
    For large K, minimal steps can be large, but once >100 we only need the count. So continue rolling DP until first success.

This is acceptable when K and answer are not astronomically huge; that is the intended contest-style interpretation.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int u, v;
        long w;
        Edge(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
    }

    static int N, M;
    static long K;
    static Edge[] edges;
    static ArrayList<Integer>[] g, rg;

    // Tarjan SCC
    static int time = 0, sccCnt = 0;
    static int[] disc, low, comp;
    static boolean[] inStack;
    static ArrayDeque<Integer> stack = new ArrayDeque<>();
    static ArrayList<ArrayList<Integer>> comps = new ArrayList<>();

    static void tarjanDFS(int u) {
        disc[u] = low[u] = ++time;
        stack.push(u);
        inStack[u] = true;
        for (int v : g[u]) {
            if (disc[v] == 0) {
                tarjanDFS(v);
                low[u] = Math.min(low[u], low[v]);
            } else if (inStack[v]) {
                low[u] = Math.min(low[u], disc[v]);
            }
        }
        if (low[u] == disc[u]) {
            ArrayList<Integer> list = new ArrayList<>();
            while (true) {
                int x = stack.pop();
                inStack[x] = false;
                comp[x] = sccCnt;
                list.add(x);
                if (x == u) break;
            }
            comps.add(list);
            sccCnt++;
        }
    }

    static boolean hasPositiveCycle() {
        disc = new int[N];
        low = new int[N];
        comp = new int[N];
        inStack = new boolean[N];
        for (int i = 0; i < N; i++) {
            if (disc[i] == 0) tarjanDFS(i);
        }

        ArrayList<Edge>[] byComp = new ArrayList[sccCnt];
        for (int i = 0; i < sccCnt; i++) byComp[i] = new ArrayList<>();
        int[] sz = new int[sccCnt];
        for (int i = 0; i < sccCnt; i++) sz[i] = comps.get(i).size();

        for (Edge e : edges) {
            if (comp[e.u] == comp[e.v]) byComp[comp[e.u]].add(e);
        }

        for (int c = 0; c < sccCnt; c++) {
            ArrayList<Integer> verts = comps.get(c);
            ArrayList<Edge> es = byComp[c];
            if (es.isEmpty()) continue;

            // Need at least a cycle candidate:
            if (verts.size() == 1) {
                int u = verts.get(0);
                boolean selfLoop = false;
                for (Edge e : es) {
                    if (e.u == u && e.v == u) {
                        selfLoop = true;
                        if (e.w > 0) return true;
                    }
                }
                if (!selfLoop) continue;
            }

            // Longest-path relaxation inside SCC:
            // initialize all 0 (can start anywhere in SCC)
            HashMap<Integer, Integer> id = new HashMap<>();
            for (int i = 0; i < verts.size(); i++) id.put(verts.get(i), i);
            long[] dist = new long[verts.size()];
            boolean improved = false;
            for (int iter = 0; iter < verts.size(); iter++) {
                improved = false;
                for (Edge e : es) {
                    int u = id.get(e.u), v = id.get(e.v);
                    if (dist[u] + e.w > dist[v]) {
                        dist[v] = dist[u] + e.w;
                        improved = true;
                    }
                }
                if (!improved) break;
            }
            if (improved) return true; // improvement on |V|-th iteration => positive cycle
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        M = fs.nextInt();
        K = fs.nextLong();

        edges = new Edge[M];
        g = new ArrayList[N];
        rg = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }

        long maxSingle = Long.MIN_VALUE;
        int maxSingleU = -1, maxSingleV = -1;

        for (int i = 0; i < M; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            long w = fs.nextLong();
            edges[i] = new Edge(u, v, w);
            g[u].add(v);
            rg[v].add(u);
            if (w > maxSingle) {
                maxSingle = w;
                maxSingleU = u;
                maxSingleV = v;
            }
        }

        if (K <= 0) {
            // zero edges, choose any cone
            System.out.println(0);
            System.out.println(1);
            return;
        }

        if (M == 0) {
            System.out.println(-1);
            return;
        }

        boolean posCycle = hasPositiveCycle();

        long NEG = Long.MIN_VALUE / 4;
        long[] cur = new long[N];
        Arrays.fill(cur, 0L); // can start at any cone with 0 score and 0 edges

        int limitNoCycle = N - 1;
        int t = 0;

        int[][] parent = new int[Math.min(101, 100 + 1)][];
        if (100 >= 0) {
            parent[0] = new int[N];
            Arrays.fill(parent[0], -1);
        }

        while (true) {
            t++;
            long[] next = new long[N];
            Arrays.fill(next, NEG);
            int[] par = null;
            if (t <= 100) {
                par = new int[N];
                Arrays.fill(par, -2);
            }

            for (Edge e : edges) {
                if (cur[e.u] == NEG) continue;
                long cand = cur[e.u] + e.w;
                if (cand > next[e.v]) {
                    next[e.v] = cand;
                    if (t <= 100) par[e.v] = e.u;
                }
            }

            int end = -1;
            for (int v = 0; v < N; v++) {
                if (next[v] >= K) {
                    end = v;
                    break;
                }
            }

            if (t <= 100) parent[t] = par;

            if (end != -1) {
                StringBuilder sb = new StringBuilder();
                sb.append(t).append('\n');
                if (t <= 100) {
                    int[] path = new int[t + 1];
                    path[t] = end;
                    for (int i = t; i >= 1; i--) {
                        path[i - 1] = parent[i][path[i]];
                    }
                    for (int i = 0; i <= t; i++) {
                        if (i > 0) sb.append(' ');
                        sb.append(path[i] + 1);
                    }
                    sb.append('\n');
                }
                System.out.print(sb.toString());
                return;
            }

            cur = next;

            if (!posCycle && t >= limitNoCycle) {
                System.out.println(-1);
                return;
            }
        }
    }
}
